import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  cardClassName,
  cardContentClassName,
  cardDescriptionClassName,
  cardFooterClassName,
  cardHeaderClassName,
  cardTitleClassName,
} from "./view";

export {
  cardClassName,
  cardContentClassName,
  cardDescriptionClassName,
  cardFooterClassName,
  cardHeaderClassName,
  cardTitleClassName,
} from "./view";

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const view = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div([h.Class(classNames(cardClassName, className))], children);
};

export const headerView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div([h.Class(classNames(cardHeaderClassName, className))], children);
};

export const titleView = <ParentMessage>(
  label: string,
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.h3([h.Class(classNames(cardTitleClassName, className))], [label]);
};

export const descriptionView = <ParentMessage>(
  label: string,
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.p(
    [h.Class(classNames(cardDescriptionClassName, className))],
    [label]
  );
};

export const contentView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div(
    [h.Class(classNames(cardContentClassName, className))],
    children
  );
};

export const footerView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();
  return h.div([h.Class(classNames(cardFooterClassName, className))], children);
};

export const cardClassName =
  "rounded-lg border border-gray-200 bg-white text-gray-950 shadow-sm";

export const cardHeaderClassName = "flex flex-col gap-1.5 p-6";

export const cardTitleClassName =
  "text-lg font-semibold leading-none tracking-normal text-gray-950";

export const cardDescriptionClassName = "text-sm text-gray-600";

export const cardContentClassName = "p-6 pt-0";

export const cardFooterClassName =
  "flex items-center justify-between gap-3 border-t border-gray-200 p-6";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Card from "./index";

const view = (): Html => {
  const h = html<never>();

  return Card.view([
    Card.headerView([
      Card.titleView("Project health"),
      Card.descriptionView(
        "Current registry progress and verification status."
      ),
    ]),
    Card.contentView([h.p([], ["Ready"])]),
    Card.footerView([h.span([], ["Public"])]),
  ]);
};

describe("Card registry view", () => {
  test("renders the documented static surface", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Project health")).toExist(),
      Scene.expect(
        Scene.text("Current registry progress and verification status.")
      ).toExist()
    );
  });
});
